target.css:
:root {
  --ink: #172235;
  --muted: #667085;
  --paper: #ffffff;
  --line: #dce2ea;
  --blue: #246bce;
  --blue-pale: #eaf2ff;
  --lime: #287a4d;
  --lime-pale: #e7f6ed;
  --amber: #a85f08;
  --amber-pale: #fff2d9;
  --navy: #21365c;
  --preview: #dfe9fb;
}

* {
  box-sizing: border-box;
}

.proof-board {
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.board-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.title-block p,
.section-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  margin-top: 3px;
  font-size: 20px;
  line-height: 1.1;
  letter-spacing: -0.035em;
}

h2 {
  margin-top: 4px;
  font-size: 15px;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.state {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--lime-pale);
  color: var(--lime);
  font-size: 11px;
  font-weight: 750;
}

.state::before {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--lime);
  content: "";
}

.workspace {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 12px;
  padding: 12px 16px;
}

.batch-card,
.checks {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.batch-card {
  padding: 12px;
  background: var(--paper);
}

.batch-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.reel-tag {
  padding: 4px 6px;
  border-radius: 5px;
  background: var(--blue-pale);
  color: var(--blue);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.batch-meta {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
  margin: 12px 0;
}

.batch-meta div {
  padding-left: 7px;
  border-left: 2px solid var(--preview);
}

.batch-meta dt {
  color: var(--muted);
  font-size: 9px;
  line-height: 1.2;
}

.batch-meta dd {
  margin: 2px 0 0;
  color: var(--ink);
  font-size: 10px;
  font-weight: 750;
  line-height: 1.2;
}

.frame-preview {
  position: relative;
  display: grid;
  grid-template-columns: 28px 1fr;
  grid-template-rows: repeat(3, 1fr) auto;
  gap: 4px 8px;
  height: 57px;
  margin: 0;
  padding: 8px;
  overflow: hidden;
  border-radius: 8px;
  background: var(--navy);
}

.frame-number {
  grid-row: 1 / 4;
  align-self: center;
  color: var(--preview);
  font-size: 16px;
  font-weight: 800;
  letter-spacing: -0.04em;
}

.scan-line {
  align-self: center;
  height: 4px;
  border-radius: 99px;
  background: var(--preview);
}

.line-one { width: 88%; }
.line-two { width: 68%; }
.line-three { width: 80%; }

figcaption {
  grid-column: 1 / -1;
  color: var(--preview);
  font-size: 9px;
  line-height: 1;
}

.checks {
  display: flex;
  flex-direction: column;
  padding: 12px;
  background: var(--blue-pale);
}

.check-list {
  display: grid;
  gap: 5px;
  margin: 12px 0 8px;
  padding: 0;
  list-style: none;
}

.check-list li {
  display: grid;
  grid-template-columns: 9px 1fr auto;
  align-items: center;
  gap: 6px;
  color: var(--ink);
  font-size: 11px;
}

.check-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.check-dot.pass { background: var(--lime); }
.check-dot.review { background: var(--amber); }

.check-list strong {
  font-size: 10px;
  font-weight: 800;
}

.note {
  margin-top: auto;
  padding-top: 8px;
  border-top: 1px solid var(--line);
  color: var(--amber);
  font-size: 10px;
  line-height: 1.3;
}

.board-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
}

.board-footer p {
  color: var(--muted);
  font-size: 11px;
}

.board-footer p span {
  color: var(--ink);
  font-weight: 800;
}

button {
  border: 0;
  border-radius: 8px;
  padding: 8px 10px;
  background: var(--blue);
  color: var(--paper);
  font-size: 11px;
  font-weight: 750;
}

button span {
  margin-left: 5px;
  font-size: 14px;
  line-height: 0;
}

